    }), "\n", _jsx(_components.h2, {
      children: "Advanced Patterns: Partial Responses and Field Selection"
    }), "\n", _jsxs(_components.p, {
      children: ["Field selection parameters let clients specify which fields they want in responses, reducing bandwidth and improving performance by avoiding over-fetching. The common implementation uses query strings: ", _jsx(_components.code, {
